CREATE TABLE IF NOT EXISTS workspaces (id text PRIMARY KEY, name text NOT NULL, sample boolean NOT NULL DEFAULT false, reference_date text NOT NULL);
CREATE TABLE IF NOT EXISTS agents (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), name text NOT NULL, role text NOT NULL, initials text NOT NULL, color text NOT NULL, email text NOT NULL, style jsonb NOT NULL, UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS clients (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, name text NOT NULL, email text NOT NULL, phone text NOT NULL, type text NOT NULL, notes jsonb NOT NULL DEFAULT '[]', UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id));
CREATE TABLE IF NOT EXISTS properties (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text NOT NULL, address text NOT NULL, city text NOT NULL, price integer NOT NULL CHECK(price >= 0), beds integer NOT NULL, baths integer NOT NULL, sqft integer NOT NULL, stage text NOT NULL, image text NOT NULL, description text NOT NULL, notes jsonb NOT NULL DEFAULT '[]', target_date text, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id));
CREATE TABLE IF NOT EXISTS conversations (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text NOT NULL, property_id text, title text NOT NULL, transcript text NOT NULL, source text NOT NULL CHECK(source IN ('note','audio','sample')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id));
CREATE TABLE IF NOT EXISTS work_packages (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), conversation_id text NOT NULL, agent_id text NOT NULL, client_id text NOT NULL, property_id text, title text NOT NULL, summary text NOT NULL, facts jsonb NOT NULL, clarifications jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewed')), origin text NOT NULL CHECK(origin IN ('sample','openai')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id));
CREATE TABLE IF NOT EXISTS proposed_actions (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), package_id text NOT NULL, position integer NOT NULL, kind text NOT NULL CHECK(kind IN ('summary','crm_note','message','task','listing_update')), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), due_date text, source_quote text NOT NULL, certainty text NOT NULL CHECK(certainty IN ('confirmed','requested','uncertain')), reviewed_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,package_id) REFERENCES work_packages(workspace_id,id));
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text, property_id text, title text NOT NULL, detail text NOT NULL, due_date text, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), priority text NOT NULL CHECK(priority IN ('high','normal')), source text NOT NULL, source_action_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id), FOREIGN KEY(workspace_id,source_action_id) REFERENCES proposed_actions(workspace_id,id));
CREATE TABLE IF NOT EXISTS appointments (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text, property_id text, title text NOT NULL, starts_at text NOT NULL, ends_at text NOT NULL, location text NOT NULL, status text NOT NULL CHECK(status IN ('confirmed','tentative')), briefing text NOT NULL, FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id));
CREATE TABLE IF NOT EXISTS activities (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text, property_id text, title text NOT NULL, detail text NOT NULL, kind text NOT NULL, source_action_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id), FOREIGN KEY(workspace_id,source_action_id) REFERENCES proposed_actions(workspace_id,id));
CREATE TABLE IF NOT EXISTS approved_messages (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, client_id text NOT NULL, property_id text, source_action_id text NOT NULL UNIQUE, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'approved' CHECK(status='approved'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id), FOREIGN KEY(workspace_id,source_action_id) REFERENCES proposed_actions(workspace_id,id));
CREATE INDEX IF NOT EXISTS tasks_workspace_agent_idx ON tasks(workspace_id,agent_id,status);
CREATE INDEX IF NOT EXISTS packages_workspace_agent_idx ON work_packages(workspace_id,agent_id,status);
CREATE INDEX IF NOT EXISTS actions_workspace_package_idx ON proposed_actions(workspace_id,package_id);
CREATE INDEX IF NOT EXISTS activities_workspace_created_idx ON activities(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS conversations_workspace_agent_idx ON conversations(workspace_id,agent_id);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS review_package_id text;
ALTER TABLE tasks ADD CONSTRAINT tasks_review_package_fk FOREIGN KEY(workspace_id,review_package_id) REFERENCES work_packages(workspace_id,id);
